query_sql:
/*Changes made by  Syeravadekar-  09-15-2021
Adding filter for contact_type, fix for missing state values and missing stu_hs_grad_level calc and stu_hs_grad_year values and making it swap compliant
ESDP 746, 747, 692 , 757
-- made changes to populate partner_id from school_panto_id to school_panto_guid
-- Made changes to Null out the international addresses
*/
--Madhvi v1.0 10/29/2021 Remove duplicates from xwalk


select  distinct  NULLIF(TRIM(Con.first_name), '')   as   firstname ,  NULLIF(TRIM(Con.last_name), '')   as   lastname ,  TRIM(Con.email_address)   as   email ,  case when Lower(SCCA.country) = 'united states' then NULLIF(TRIM(SCCA.ADDR_1), '') else null end   as   address1 ,  case when Lower(SCCA.country) = 'united states' then NULLIF(TRIM(SCCA.ADDR_2), '') else null end   as   address2 ,  case when Lower(SCCA.country) = 'united states' then NULLIF(TRIM(SCCA.city), '') else null end   as   city ,  case when Lower(SCCA.country) = 'united states' then NULLIF(TRIM(state_translation.eabstandard_value), '') else null end   as   state ,  TRIM(case when INITCAP(SCCA.country) = 'Unknown' or lower(SCCA.country) = 'unmapped value' then null else SCCA.country end)   as   country ,  TRIM(case when Lower(SCCA.country) = 'united states' then SCCA.ZIP5 else null end)   as   zipcode ,  TRIM(SCCA.CREATE_DT)   as   CREATE_DTS ,  TRIM(Con.phone_number)   as   mobile ,  TRIM(Con.distance_from_campus)   as   dist_from_campus_calc ,  TRIM(AC.is_deleted)   as   is_deleted ,  TRIM(race_stdz.race)   as   race_stdzd ,  TRIM(Con.ethnicity)   as   ethnicity_stdzd ,  null   as   religion_partner ,  TRIM(ac_blnd.academic_interest_blnd)   as   academic_field_intrst_bln ,  TRIM(Con.contact_key)   as   eab_contact_id ,  NULLIF(TRIM(Con.contact_type_calc), '')   as   eab_contact_type ,  INITCAP(NULLIF(TRIM(Con.funnel_status_calc), ''))   as   funnel_stage_calc ,  TRIM(AC.student_application_status)   as   student_app_status ,  TRIM(AC.form_student_first_name)   as   form_student_first_name ,  TRIM(AC.form_student_last_name)   as   form_student_last_name ,  TRIM(AC.form_parent_first_name)   as   form_parent_first_name ,  TRIM(AC.form_parent_last_name)   as   form_parent_last_name ,  TRIM(AC.form_parent_email)   as   form_parent_email ,  TRIM(AC.form_referred_by_EAB_ID)   as   form_referred_by_EAB_ID ,  TRIM(label.source_label)   as   og_contact_source_calc ,  TRIM(all_source.all_sources_blnd)   as   all_sources_blnd ,  TRIM(AC.FORM_H_SCHOOL_NAME)   as   form_h_school_name ,  TRIM(AC.FORM_H_SCHOOL_ADDR)   as   form_h_school_addr ,  TRIM(AC.FORM_H_SCHOOL_CITY)   as   form_h_school_city ,  TRIM(AC.FORM_H_SCHOOL_STATEPROV)   as   form_h_school_stateprov ,  TRIM(AC.FORM_H_SCHOOL_POST_CODE)   as   form_h_school_post_code ,  TRIM(AC.FORM_H_SCHOOL_COUNTRY)   as   form_h_school_country ,  TRIM(AC.FORM_H_SCHOOL_GRAD_YEAR)   as   form_h_school_grad_year ,  TRIM(AC.FORM_ENTRY_YEAR)   as   form_entry_year ,  TRIM(Con.current_grade_level)   as   h_school_grade_level_calc ,  TRIM(Con.grad_year)   as   h_school_grad_year_calc ,  TRIM(max_values.sat_max)   as   max_sat_score_rng_calc ,  TRIM(max_values.act_max)   as   max_act_score_rng_calc ,  TRIM(max_values.psat_max)   as   max_psat_score_rng_calc ,  TRIM(max_values.preact_max)   as   max_preact_score_rng_calc ,  null   as   fafsa_submit_date_partner ,  TRIM(Con.contact_rand)   as   random_number ,  TRIM(AC.FORM_BOT_HONEYPOT)   as   form_bot_honeypot ,  case when AC.ACS_REPLICATION_DATE IS NOT NULL then CONCAT(LEFT(REPLACE(TRIM(AC.ACS_REPLICATION_DATE), ' ', 'T'), 19), '+00:00') else null end   as   acs_replication_date ,  TRIM(xwalk.print_display_id)   as   print_display_id ,  TRIM(PD.PANTO_SCHOOL_GUID)   as   es_partner_id ,  TRIM(AC.FORM_ACADEMIC_FIELD_INTRS)   as   Form_Academic_Field_Intrs ,  TRIM(AC.FORM_EMAIL_UPDATE_CONTACT_KEY)   as   FORM_EMAIL_UPDATED_EAB_ID ,  TRIM(AC.Form_Student_Addr)   as   FORM_STUDENT_ADDR ,  TRIM(AC.Form_Student_City)   as   FORM_STUDENT_CITY ,  TRIM(AC.Form_Student_Stateprov)   as   form_student_stateprov ,  TRIM(AC.Form_Student_Post_Code)   as   form_student_post_code ,  TRIM(AC.Form_Student_Country)   as   form_student_country ,  TRIM(AC.Form_Sms_Opt_In)   as   form_sms_opt_in ,  TRIM(AC.Engaged_Inq_Cmpgn_Acsl)   as   engaged_inq_cmpgn_acsl ,  TRIM(AC.Engaged_Reeng_Cmpgn_Acsl)   as   engaged_reeng_cmpgn_acsl ,  TRIM(parent.FIRST_NAME)   as   child_first_name_calc ,  TRIM(parent.LAST_NAME)   as   child_last_name_calc ,  TRIM(case when Con.suppress_mail_ind = 1 then 'Y' else 'N' end)   as   do_not_direct_mail_calc ,  case when lower(optin_sms_indicator) = 'false' then 'false' when lower(optin_sms_indicator) = 'true' then 'true' else null end   as   sms_opt_in_calc ,  TRIM(case when Con.suppress_email_ind = 1 then 'TRUE' else 'FALSE' end)   as   dnc_email ,  null   as   dnc_email_comment ,  PHN.optin_sms_indicator ,  case when Con.contact_type_calc = 'Parent/Guardian' then parent.stu_hs_grade_level_calc else Con.current_grade_level end   as   stu_hs_grade_level_calc ,  TRIM(Con.grad_year)   as   high_school_grad_year_calculated ,  null   as   student_funnel_stage_calc ,  INITCAP(NULLIF(TRIM(parent.student_funnel_stage_calc), ''))   as   stu_funnel_stage_calc ,  TRIM(AC.student_application_status)   as   stu_eab_app_status ,  TRIM(ac_blnd.academic_interest_blnd)   as   stu_aca_field_intrst_blnd ,  TRIM(race_stdz.race)   as   stu_race_stdzd ,  TRIM(Con.ethnicity)   as   stu_ethnicity_stdzd ,  null   as   stu_religion_partner ,  case when Con.contact_type_calc = 'Parent/Guardian' then parent.high_school_grad_year_calculated else Con.grad_year end   as   stu_hs_grad_year_calc ,  ac.eng_app_par_gen_acsl   as   eng_app_par_gen_acsl ,  ac.eng_app_stu_gen_acsl   as   eng_app_stu_gen_acsl ,  ac.eng_app_stu_paper_acsl   as   eng_app_stu_paper_acsl ,  ac.eng_app_stu_sub_acsl   as   eng_app_stu_sub_acsl ,  ac.eng_cul_par_inq_acsl   as   eng_cul_par_inq_acsl ,  ac.eng_cul_par_nur_acsl   as   eng_cul_par_nur_acsl ,  ac.eng_cul_stu_inq_acsl   as   eng_cul_stu_inq_acsl ,  ac.eng_cul_stu_paper_acsl   as   eng_cul_stu_paper_acsl ,  ac.eng_cul_stu_nur_acsl   as   eng_cul_stu_nur_acsl ,  ac.eng_cul_stu_reen_acsl   as   eng_cul_stu_reen_acsl ,  ac.eng_cul_stu_j_reen_acsl   as   eng_cul_stu_j_reen_acsl ,  ac.eng_cul_stu_sms_acsl   as   eng_cul_stu_sms_acsl ,  ac.st_dt_app_par_gen_acsl   as   st_dt_app_par_gen_acsl ,  ac.st_dt_app_stu_gen_acsl   as   st_dt_app_stu_gen_acsl ,  ac.st_dt_app_stu_paper_acsl   as   st_dt_app_stu_paper_acsl ,  ac.st_dt_cul_par_inq_acsl   as   st_dt_cul_par_inq_acsl ,  ac.st_dt_cul_par_nur_acsl   as   st_dt_cul_par_nur_acsl ,  ac.st_dt_cul_stu_inq_acsl   as   st_dt_cul_stu_inq_acsl ,  ac.st_dt_cul_stu_paper_acsl   as   st_dt_cul_stu_paper_acsl ,  ac.st_dt_cul_stu_nur_acsl   as   st_dt_cul_stu_nur_acsl ,  ac.st_dt_cul_stu_j_reen_acsl   as   st_dt_cul_stu_j_reen_acsl ,  ac.st_dt_cul_stu_reen_acsl   as   st_dt_cul_stu_reen_acsl ,  ac.st_dt_cul_stu_sms_acsl   as   st_dt_cul_stu_sms_acsl 

from   PDP.con__contact_assigned as Con left join PDP.add__sourcecontact_clean_addr as SCCA on Con.CLEAN_ADDR_KEY = SCCA.CLEAN_ADDR_KEY
Left join ( SELECT distinct Contact_key, dummy_email ,acs_contact_id,print_display_id
			  FROM (
					  SELECT  CAC.CONTACT_KEY Contact_key, CAC.DUMMY_EMAIL dummy_email, CAC.ACS_CONTACT_ID acs_contact_id,CAC.print_display_id,
							  row_number() over (partition by CAC.CONTACT_KEY order by CAC.CREATE_DT asc) rnum
					FROM PDP.prc__contact_acquia_xwalk as CAC
					) as xw where xw.rnum=1 ) as xwalk 
on con.Contact_key = xwalk.Contact_key
left join PDP.acs__contacts as AC on xwalk.acs_contact_id = AC.acs_contact_id left join  <[Partner_Data_Platform].[Phone]>  as PHN on PHN.phone_number = Con.phone_number left join (
select   Con.FIRST_NAME ,  Con.LAST_NAME ,  Con.CONTACT_KEY 
from   PDP.con__contact_assigned as Con left join PDP.con__contact_relations as d on Con.CONTACT_KEY = d.student_contact_key 
where  initcap(Con.contact_type_calc) = 'Parent/Guardian'
) as child_names on child_names.CONTACT_KEY = Con.CONTACT_KEY left join (
select   CTS_PIVOT.contact_key   as   contact_key ,  CTS_PIVOT.sourcecontact_id   as   sourcecontact_id ,  max(sat_max)   as   sat_max ,  max(act_max)   as   act_max ,  max(psat_max)   as   psat_max ,  max(preact_max)   as   preact_max 
from   (
select   CTS.contact_key   as   contact_key ,  CTS.sourcecontact_id ,  case when UPPER(CTS.test_type) = 'SAT' then CTS.score_range_max else null end   as   sat_max ,  case when UPPER(CTS.test_type) = 'ACT' then CTS.score_range_max else null end   as   act_max ,  case when UPPER(CTS.test_type) = 'PSAT' then CTS.score_range_max else null end   as   psat_max ,  case when UPPER(CTS.test_type) = 'PREACT' then CTS.score_range_max else null end   as   preact_max 
from   PDP.con__contact_test_scores as CTS 
) as CTS_PIVOT 
group by   CTS_PIVOT.contact_key, CTS_PIVOT.sourcecontact_id 
) as max_values on Con.contact_key = max_values.contact_key and Con.active_sourcecontact_id = max_values.sourcecontact_id left join  <[Partner_Data_Platform].[Sourcecontact Sourcetype]>  as srccontact_srctype on srccontact_srctype. <Source Contact ID>  = Con.active_sourcecontact_id left join pdp.crf__intake_type as srctype on srccontact_srctype. <Source Type Key>  = srctype.intake_type_key left outer join es_pdp_common.common.common_source_standard_mappings as state_translation on UPPER(state_translation.source_type) = 'GENERAL' and Upper(state_translation.Category) = 'STATE' and Lower(state_translation.SOURCE_FIELD_NAME) = 'state' and lower(state_translation.eabstandard_value) = lower(SCCA.state) left join (
select   a.contact_key ,  LISTAGG(a.eab_std_value, '|')   as   academic_interest_blnd 
from   (
select  distinct  b.contact_key ,  b.eab_std_value ,  b.attribute_type 
from   PDP.con__contact_attributes_combined as b 
) as a 
where  Lower(a.attribute_type) = 'academic_interest'
group by   a.contact_key 
) as ac_blnd on Con.contact_key = ac_blnd.contact_key left join (
select   a.contact_key ,  a.sourcecontact_id ,  LISTAGG(a.eab_std_value, '|')   as   race 
from   (
select  distinct  b.contact_key ,  b.sourcecontact_id ,  b.eab_std_value ,  b.attribute_type 
from   PDP.con__contact_attributes_combined as b 
) as a 
where  Lower(a.attribute_type) = 'race'
group by   a.contact_key, a.sourcecontact_id 
) as race_stdz on Con.contact_key = race_stdz.contact_key and Con.active_sourcecontact_id = race_stdz.sourcecontact_id left join (
select   list_sources.contact_key ,  LISTAGG(list_sources.all_source_bln_list_agg, '|')   as   all_sources_blnd 
from   (
select   contact_key ,  case when lower(intake_type_label) = 'prenames' then 'Migrated Contact' else null end   as   all_source_bln_list_agg 
from   PDP.crf__contact_sourcecontacts as CSCS left join pdp.crf__intake_type as intake on CSCS.source_type_key = intake.intake_type_key 
where  LOWER(CSCS.active_ind) = 'true' and lower(intake_type_label) = 'prenames'
 UNION 
select  distinct  contact_key ,  source_label   as   all_source_bln_list_agg 
from   PDP.crf__contact_sourcecontacts as CSCS inner join pdp.crf__source as srctype on CSCS.source_key = srctype.source_key 
where  LOWER(CSCS.active_ind) = 'true'
) as list_sources 
group by   list_sources.contact_key 
) as all_source on Con.contact_key = all_source.contact_key left join (
select   con3.first_name ,  con3.last_name ,  con3.parent_contact_key ,  con3.student_contact_key ,  con3.stu_hs_grade_level_calc   as   stu_hs_grade_level_calc ,  con3.high_school_grad_year_calculated   as   high_school_grad_year_calculated ,  con3.student_funnel_stage_calc   as   student_funnel_stage_calc 
from   (
select  distinct  con2.first_name ,  con2.last_name ,  con2.parent_contact_key ,  con2.student_contact_key ,  con2.stu_hs_grade_level_calc   as   stu_hs_grade_level_calc ,  con2.high_school_grad_year_calculated   as   high_school_grad_year_calculated ,  con2.student_funnel_stage_calc   as   student_funnel_stage_calc ,  row_number() over (partition by con2.parent_contact_key order by  con2.sourcecontact_intake_dt   ASC )   as   rankid2 
from   (
select  distinct  rel.parent_contact_key ,  rel.student_contact_key ,  scst.create_date   as   sourcecontact_intake_dt ,  con1.current_grade_level   as   stu_hs_grade_level_calc ,  con1.grad_year   as   high_school_grad_year_calculated ,  con1.first_name ,  con1.last_name ,  con1.funnel_status_calc   as   student_funnel_stage_calc ,  row_number() over (partition by rel.parent_contact_key order by  int.INTAKE_PRIORITY   ASC )   as   rankid 
from   PDP.con__contact_assigned as con inner join PDP.crf__contact_sourcecontacts as src on con.contact_key = src.contact_key inner join pdp.crf__intake_type as int on int.intake_type_key = src.source_type_key inner join  <[Partner_Data_Platform].[SourceContact SourceType]>  as scst on src.sourcecontact_id = scst.source_contact_id left join PDP.con__contact_relations as rel on rel.parent_contact_key = con.contact_key left join PDP.con__contact_assigned as con1 on rel.student_contact_key = con1.contact_key 
where  con.contact_type_calc = 'Parent/Guardian'
) as con2 
where  rankid = 1
) as con3 
where  rankid2 = 1
) as parent on Con.contact_key = parent.parent_contact_key left join (
select   sub_1.contact_key ,  sub_1.source_label   as   source_label 
from   (
select   ROW_NUMBER() over (partition by contact_key order by  CSCTS.create_dt   ASC )   as   row_id ,  CSCTS.contact_key ,  srctype.source_label 
from   PDP.crf__contact_sourcecontacts as CSCTS inner join pdp.crf__source as srctype on CSCTS.source_key = srctype.source_key 
) as sub_1 
where  row_id = 1
) as label on Con.contact_key = label.contact_key inner join PDP.prc__partner_details as PD 

 where (NULLIF(TRIM(Con.contact_type_calc ), '')   in  ('Student','Parent/Guardian', 'Ride Along','Deliverability Seed')and ((TRIM(label.source_label) is not null and TRIM(all_source.all_sources_blnd) is not null)) and lower(Con.email_address ) not like '%test.eab.com') and Con.email_address not in ('itimmenschuh@gmail.com') or (NULLIF(TRIM(Con.contact_type_calc ), '') in ('Deliverability Seed', 'Ride Along') and TRIM(all_source.all_sources_blnd) is null and lower(Con.email_address ) not like '%test.eab.com')

/*Changes made by  Syeravadekar-  09-15-2021
Adding filter for contact_type, fix for missing state values and missing stu_hs_grad_level calc and stu_hs_grad_year values and making it swap compliant
ESDP 746, 747, 692 , 757
-- made changes to populate partner_id from school_panto_id to school_panto_guid
-- Made changes to Null out the international addresses
*/
--Madhvi v1.0 10/29/2021 Remove duplicates from xwalk



select  distinct  NULLIF(TRIM(Con.first_name), '')   as   firstname ,  NULLIF(TRIM(Con.last_name), '')   as   lastname ,  TRIM(Con.email_address)   as   email ,  case when Lower(SCCA.country) = 'united states' then NULLIF(TRIM(SCCA.ADDR_1), '') else null end   as   address1 ,  case when Lower(SCCA.country) = 'united states' then NULLIF(TRIM(SCCA.ADDR_2), '') else null end   as   address2 ,  case when Lower(SCCA.country) = 'united states' then NULLIF(TRIM(SCCA.city), '') else null end   as   city ,  case when Lower(SCCA.country) = 'united states' then NULLIF(TRIM(state_translation.eabstandard_value), '') else null end   as   state ,  TRIM(case when INITCAP(SCCA.country) = 'Unknown' or lower(SCCA.country) = 'unmapped value' then null else SCCA.country end)   as   country ,  TRIM(case when Lower(SCCA.country) = 'united states' then SCCA.ZIP5 else null end)   as   zipcode ,  TRIM(SCCA.CREATE_DT)   as   CREATE_DTS ,  TRIM(Con.phone_number)   as   mobile ,  TRIM(Con.distance_from_campus)   as   dist_from_campus_calc ,  TRIM(AC.is_deleted)   as   is_deleted ,  TRIM(race_stdz.race)   as   race_stdzd ,  TRIM(Con.ethnicity)   as   ethnicity_stdzd ,  null   as   religion_partner ,  TRIM(ac_blnd.academic_interest_blnd)   as   academic_field_intrst_bln ,  TRIM(Con.contact_key)   as   eab_contact_id ,  NULLIF(TRIM(Con.contact_type_calc), '')   as   eab_contact_type ,  INITCAP(NULLIF(TRIM(Con.funnel_status_calc), ''))   as   funnel_stage_calc ,  TRIM(AC.student_application_status)   as   student_app_status ,  TRIM(AC.form_student_first_name)   as   form_student_first_name ,  TRIM(AC.form_student_last_name)   as   form_student_last_name ,  TRIM(AC.form_parent_first_name)   as   form_parent_first_name ,  TRIM(AC.form_parent_last_name)   as   form_parent_last_name ,  TRIM(AC.form_parent_email)   as   form_parent_email ,  TRIM(AC.form_referred_by_EAB_ID)   as   form_referred_by_EAB_ID ,  TRIM(label.source_label)   as   og_contact_source_calc ,  TRIM(all_source.all_sources_blnd)   as   all_sources_blnd ,  TRIM(AC.FORM_H_SCHOOL_NAME)   as   form_h_school_name ,  TRIM(AC.FORM_H_SCHOOL_ADDR)   as   form_h_school_addr ,  TRIM(AC.FORM_H_SCHOOL_CITY)   as   form_h_school_city ,  TRIM(AC.FORM_H_SCHOOL_STATEPROV)   as   form_h_school_stateprov ,  TRIM(AC.FORM_H_SCHOOL_POST_CODE)   as   form_h_school_post_code ,  TRIM(AC.FORM_H_SCHOOL_COUNTRY)   as   form_h_school_country ,  TRIM(AC.FORM_H_SCHOOL_GRAD_YEAR)   as   form_h_school_grad_year ,  TRIM(AC.FORM_ENTRY_YEAR)   as   form_entry_year ,  TRIM(Con.current_grade_level)   as   h_school_grade_level_calc ,  TRIM(Con.grad_year)   as   h_school_grad_year_calc ,  TRIM(max_values.sat_max)   as   max_sat_score_rng_calc ,  TRIM(max_values.act_max)   as   max_act_score_rng_calc ,  TRIM(max_values.psat_max)   as   max_psat_score_rng_calc ,  TRIM(max_values.preact_max)   as   max_preact_score_rng_calc ,  null   as   fafsa_submit_date_partner ,  TRIM(Con.contact_rand)   as   random_number ,  TRIM(AC.FORM_BOT_HONEYPOT)   as   form_bot_honeypot ,  case when AC.ACS_REPLICATION_DATE IS NOT NULL then CONCAT(LEFT(REPLACE(TRIM(AC.ACS_REPLICATION_DATE), ' ', 'T'), 19), '+00:00') else null end   as   acs_replication_date ,  TRIM(xwalk.print_display_id)   as   print_display_id ,  TRIM(PD.PANTO_SCHOOL_GUID)   as   es_partner_id ,  TRIM(AC.FORM_ACADEMIC_FIELD_INTRS)   as   Form_Academic_Field_Intrs ,  TRIM(AC.FORM_EMAIL_UPDATE_CONTACT_KEY)   as   FORM_EMAIL_UPDATED_EAB_ID ,  TRIM(AC.Form_Student_Addr)   as   FORM_STUDENT_ADDR ,  TRIM(AC.Form_Student_City)   as   FORM_STUDENT_CITY ,  TRIM(AC.Form_Student_Stateprov)   as   form_student_stateprov ,  TRIM(AC.Form_Student_Post_Code)   as   form_student_post_code ,  TRIM(AC.Form_Student_Country)   as   form_student_country ,  TRIM(AC.Form_Sms_Opt_In)   as   form_sms_opt_in ,  TRIM(AC.Engaged_Inq_Cmpgn_Acsl)   as   engaged_inq_cmpgn_acsl ,  TRIM(AC.Engaged_Reeng_Cmpgn_Acsl)   as   engaged_reeng_cmpgn_acsl ,  TRIM(parent.FIRST_NAME)   as   child_first_name_calc ,  TRIM(parent.LAST_NAME)   as   child_last_name_calc ,  TRIM(case when Con.suppress_mail_ind = 1 then 'Y' else 'N' end)   as   do_not_direct_mail_calc ,  case when lower(optin_sms_indicator) = 'false' then 'false' when lower(optin_sms_indicator) = 'true' then 'true' else null end   as   sms_opt_in_calc ,  TRIM(case when Con.suppress_email_ind = 1 then 'TRUE' else 'FALSE' end)   as   dnc_email ,  null   as   dnc_email_comment ,  PHN.optin_sms_indicator ,  case when Con.contact_type_calc = 'Parent/Guardian' then parent.stu_hs_grade_level_calc else Con.current_grade_level end   as   stu_hs_grade_level_calc ,  TRIM(Con.grad_year)   as   high_school_grad_year_calculated ,  null   as   student_funnel_stage_calc ,  INITCAP(NULLIF(TRIM(parent.student_funnel_stage_calc), ''))   as   stu_funnel_stage_calc ,  TRIM(AC.student_application_status)   as   stu_eab_app_status ,  TRIM(ac_blnd.academic_interest_blnd)   as   stu_aca_field_intrst_blnd ,  TRIM(race_stdz.race)   as   stu_race_stdzd ,  TRIM(Con.ethnicity)   as   stu_ethnicity_stdzd ,  null   as   stu_religion_partner ,  case when Con.contact_type_calc = 'Parent/Guardian' then parent.high_school_grad_year_calculated else Con.grad_year end   as   stu_hs_grad_year_calc ,  ac.eng_app_par_gen_acsl   as   eng_app_par_gen_acsl ,  ac.eng_app_stu_gen_acsl   as   eng_app_stu_gen_acsl ,  ac.eng_app_stu_paper_acsl   as   eng_app_stu_paper_acsl ,  ac.eng_app_stu_sub_acsl   as   eng_app_stu_sub_acsl ,  ac.eng_cul_par_inq_acsl   as   eng_cul_par_inq_acsl ,  ac.eng_cul_par_nur_acsl   as   eng_cul_par_nur_acsl ,  ac.eng_cul_stu_inq_acsl   as   eng_cul_stu_inq_acsl ,  ac.eng_cul_stu_paper_acsl   as   eng_cul_stu_paper_acsl ,  ac.eng_cul_stu_nur_acsl   as   eng_cul_stu_nur_acsl ,  ac.eng_cul_stu_reen_acsl   as   eng_cul_stu_reen_acsl ,  ac.eng_cul_stu_j_reen_acsl   as   eng_cul_stu_j_reen_acsl ,  ac.eng_cul_stu_sms_acsl   as   eng_cul_stu_sms_acsl ,  ac.st_dt_app_par_gen_acsl   as   st_dt_app_par_gen_acsl ,  ac.st_dt_app_stu_gen_acsl   as   st_dt_app_stu_gen_acsl ,  ac.st_dt_app_stu_paper_acsl   as   st_dt_app_stu_paper_acsl ,  ac.st_dt_cul_par_inq_acsl   as   st_dt_cul_par_inq_acsl ,  ac.st_dt_cul_par_nur_acsl   as   st_dt_cul_par_nur_acsl ,  ac.st_dt_cul_stu_inq_acsl   as   st_dt_cul_stu_inq_acsl ,  ac.st_dt_cul_stu_paper_acsl   as   st_dt_cul_stu_paper_acsl ,  ac.st_dt_cul_stu_nur_acsl   as   st_dt_cul_stu_nur_acsl ,  ac.st_dt_cul_stu_j_reen_acsl   as   st_dt_cul_stu_j_reen_acsl ,  ac.st_dt_cul_stu_reen_acsl   as   st_dt_cul_stu_reen_acsl ,  ac.st_dt_cul_stu_sms_acsl   as   st_dt_cul_stu_sms_acsl 

from   PDP.con__contact_assigned as Con left join PDP.add__sourcecontact_clean_addr as SCCA on Con.CLEAN_ADDR_KEY = SCCA.CLEAN_ADDR_KEY
Left join ( SELECT distinct Contact_key, dummy_email ,acs_contact_id,print_display_id
			  FROM (
					  SELECT  CAC.CONTACT_KEY Contact_key, CAC.DUMMY_EMAIL dummy_email, CAC.ACS_CONTACT_ID acs_contact_id,CAC.print_display_id,
							  row_number() over (partition by CAC.CONTACT_KEY order by CAC.CREATE_DT asc) rnum
					FROM PDP.prc__contact_acquia_xwalk as CAC
					) as xw where xw.rnum=1 ) as xwalk 
on con.Contact_key = xwalk.Contact_key
left join PDP.acs__contacts as AC on xwalk.acs_contact_id = AC.acs_contact_id left join  <[Partner_Data_Platform].[Phone]>  as PHN on PHN.phone_number = Con.phone_number left join (
select   Con.FIRST_NAME ,  Con.LAST_NAME ,  Con.CONTACT_KEY 
from   PDP.con__contact_assigned as Con left join PDP.con__contact_relations as d on Con.CONTACT_KEY = d.student_contact_key 
where  initcap(Con.contact_type_calc) = 'Parent/Guardian'
) as child_names on child_names.CONTACT_KEY = Con.CONTACT_KEY left join (
select   CTS_PIVOT.contact_key   as   contact_key ,  CTS_PIVOT.sourcecontact_id   as   sourcecontact_id ,  max(sat_max)   as   sat_max ,  max(act_max)   as   act_max ,  max(psat_max)   as   psat_max ,  max(preact_max)   as   preact_max 
from   (
select   CTS.contact_key   as   contact_key ,  CTS.sourcecontact_id ,  case when UPPER(CTS.test_type) = 'SAT' then CTS.score_range_max else null end   as   sat_max ,  case when UPPER(CTS.test_type) = 'ACT' then CTS.score_range_max else null end   as   act_max ,  case when UPPER(CTS.test_type) = 'PSAT' then CTS.score_range_max else null end   as   psat_max ,  case when UPPER(CTS.test_type) = 'PREACT' then CTS.score_range_max else null end   as   preact_max 
from   PDP.con__contact_test_scores as CTS 
) as CTS_PIVOT 
group by   CTS_PIVOT.contact_key, CTS_PIVOT.sourcecontact_id 
) as max_values on Con.contact_key = max_values.contact_key and Con.active_sourcecontact_id = max_values.sourcecontact_id left join  <[Partner_Data_Platform].[Sourcecontact Sourcetype]>  as srccontact_srctype on srccontact_srctype. <Source Contact ID>  = Con.active_sourcecontact_id left join pdp.crf__intake_type as srctype on srccontact_srctype. <Source Type Key>  = srctype.intake_type_key left outer join es_pdp_common.common.common_source_standard_mappings as state_translation on UPPER(state_translation.source_type) = 'GENERAL' and Upper(state_translation.Category) = 'STATE' and Lower(state_translation.SOURCE_FIELD_NAME) = 'state' and lower(state_translation.eabstandard_value) = lower(SCCA.state) left join (
select   a.contact_key ,  LISTAGG(a.eab_std_value, '|')   as   academic_interest_blnd 
from   (
select  distinct  b.contact_key ,  b.eab_std_value ,  b.attribute_type 
from   PDP.con__contact_attributes_combined as b 
) as a 
where  Lower(a.attribute_type) = 'academic_interest'
group by   a.contact_key 
) as ac_blnd on Con.contact_key = ac_blnd.contact_key left join (
select   a.contact_key ,  a.sourcecontact_id ,  LISTAGG(a.eab_std_value, '|')   as   race 
from   (
select  distinct  b.contact_key ,  b.sourcecontact_id ,  b.eab_std_value ,  b.attribute_type 
from   PDP.con__contact_attributes_combined as b 
) as a 
where  Lower(a.attribute_type) = 'race'
group by   a.contact_key, a.sourcecontact_id 
) as race_stdz on Con.contact_key = race_stdz.contact_key and Con.active_sourcecontact_id = race_stdz.sourcecontact_id left join (
select   list_sources.contact_key ,  LISTAGG(list_sources.all_source_bln_list_agg, '|')   as   all_sources_blnd 
from   (
select   contact_key ,  case when lower(intake_type_label) = 'prenames' then 'Migrated Contact' else null end   as   all_source_bln_list_agg 
from   PDP.crf__contact_sourcecontacts as CSCS left join pdp.crf__intake_type as intake on CSCS.source_type_key = intake.intake_type_key 
where  LOWER(CSCS.active_ind) = 'true' and lower(intake_type_label) = 'prenames'
 UNION 
select  distinct  contact_key ,  source_label   as   all_source_bln_list_agg 
from   PDP.crf__contact_sourcecontacts as CSCS inner join pdp.crf__source as srctype on CSCS.source_key = srctype.source_key 
where  LOWER(CSCS.active_ind) = 'true'
) as list_sources 
group by   list_sources.contact_key 
) as all_source on Con.contact_key = all_source.contact_key left join (
select   con3.first_name ,  con3.last_name ,  con3.parent_contact_key ,  con3.student_contact_key ,  con3.stu_hs_grade_level_calc   as   stu_hs_grade_level_calc ,  con3.high_school_grad_year_calculated   as   high_school_grad_year_calculated ,  con3.student_funnel_stage_calc   as   student_funnel_stage_calc 
from   (
select  distinct  con2.first_name ,  con2.last_name ,  con2.parent_contact_key ,  con2.student_contact_key ,  con2.stu_hs_grade_level_calc   as   stu_hs_grade_level_calc ,  con2.high_school_grad_year_calculated   as   high_school_grad_year_calculated ,  con2.student_funnel_stage_calc   as   student_funnel_stage_calc ,  row_number() over (partition by con2.parent_contact_key order by  con2.sourcecontact_intake_dt   ASC )   as   rankid2 
from   (
select  distinct  rel.parent_contact_key ,  rel.student_contact_key ,  scst.create_date   as   sourcecontact_intake_dt ,  con1.current_grade_level   as   stu_hs_grade_level_calc ,  con1.grad_year   as   high_school_grad_year_calculated ,  con1.first_name ,  con1.last_name ,  con1.funnel_status_calc   as   student_funnel_stage_calc ,  row_number() over (partition by rel.parent_contact_key order by  int.INTAKE_PRIORITY   ASC )   as   rankid 
from   PDP.con__contact_assigned as con inner join PDP.crf__contact_sourcecontacts as src on con.contact_key = src.contact_key inner join pdp.crf__intake_type as int on int.intake_type_key = src.source_type_key inner join  <[Partner_Data_Platform].[SourceContact SourceType]>  as scst on src.sourcecontact_id = scst.source_contact_id left join PDP.con__contact_relations as rel on rel.parent_contact_key = con.contact_key left join PDP.con__contact_assigned as con1 on rel.student_contact_key = con1.contact_key 
where  con.contact_type_calc = 'Parent/Guardian'
) as con2 
where  rankid = 1
) as con3 
where  rankid2 = 1
) as parent on Con.contact_key = parent.parent_contact_key left join (
select   sub_1.contact_key ,  sub_1.source_label   as   source_label 
from   (
select   ROW_NUMBER() over (partition by contact_key order by  CSCTS.create_dt   ASC )   as   row_id ,  CSCTS.contact_key ,  srctype.source_label 
from   PDP.crf__contact_sourcecontacts as CSCTS inner join pdp.crf__source as srctype on CSCTS.source_key = srctype.source_key 
) as sub_1 
where  row_id = 1
) as label on Con.contact_key = label.contact_key inner join PDP.prc__partner_details as PD 

 where (NULLIF(TRIM(Con.contact_type_calc ), '')   in  ('Student','Parent/Guardian', 'Ride Along','Deliverability Seed')and ((TRIM(label.source_label) is not null and TRIM(all_source.all_sources_blnd) is not null)) and lower(Con.email_address ) not like '%test.eab.com') and Con.email_address not in ('naina.dhawan.449@k12.friscoisd.org', 'alyssa.viteri11@gmail.com', 'vicagomez13@gmail.com') or (NULLIF(TRIM(Con.contact_type_calc ), '') in ('Deliverability Seed', 'Ride Along') and TRIM(all_source.all_sources_blnd) is null and lower(Con.email_address ) not like '%test.eab.com')

