select  distinct  agg.primary_student_id ,  agg.email ,  agg.email_type ,agg.intake_dt
 
from   (
select  distinct  stud_email.primary_student_id ,  stud_email.email_address   as   email ,  case when pcm_email_type.eab_standard_value = 'Unmapped Value' then 'Unknown' else pcm_email_type.eab_standard_value end   as   email_type ,stud_email.intake_date as intake_dt
from    <[Enroll360].[Student Email].{fulfillment_ug_applicants}>  as stud_email left outer join  <[Enroll360].[Partner Code Mapping].{convert}>  as pcm_email_type on pcm_email_type.field_name = 'email_type' and coalesce(stud_email.email_type, '') = coalesce(pcm_email_type.partner_value, '') 
where   <where_statement>  union all 
select  distinct  stud_email.primary_student_id ,  stud_email.calculated_field_1   as   email ,  case when pcm_email_type.eab_standard_value = 'Unmapped Value' then 'Unknown' else pcm_email_type.eab_standard_value end   as   email_type ,stud_email.intake_date as intake_dt
from    <[Enroll360].[Student Email].{fulfillment_ug_applicants}>  as stud_email left outer join  <[Enroll360].[Partner Code Mapping].{convert}>  as pcm_email_type on pcm_email_type.field_name = 'email_type' and coalesce(stud_email.calculated_field_2, '') = coalesce(pcm_email_type.partner_value, '') 
where   <where_statement>  union all 
select  distinct  stud_email.primary_student_id ,  stud_email.calculated_field_3   as   email ,  case when pcm_email_type.eab_standard_value = 'Unmapped Value' then 'Unknown' else pcm_email_type.eab_standard_value end   as   email_type ,stud_email.intake_date as intake_dt
from    <[Enroll360].[Student Email].{fulfillment_ug_applicants}>  as stud_email left outer join  <[Enroll360].[Partner Code Mapping].{convert}>  as pcm_email_type on pcm_email_type.field_name = 'email_type' and coalesce(stud_email.calculated_field_4, '') = coalesce(pcm_email_type.partner_value, '') 
where   <where_statement>  union all 
select  distinct  stud_email.primary_student_id ,  stud_email.email_address   as   email ,  case when pcm_email_type.eab_standard_value = 'Unmapped Value' then 'Unknown' else pcm_email_type.eab_standard_value end   as   email_type ,stud_email.intake_date as intake_dt
from    <[Enroll360].[Student Email].{fulfillment_ug_inquiries}>  as stud_email left outer join  <[Enroll360].[Partner Code Mapping].{convert}>  as pcm_email_type on pcm_email_type.field_name = 'email_type' and coalesce(stud_email.email_type, '') = coalesce(pcm_email_type.partner_value, '') 
where   <where_statement>  union all 
select  distinct  stud_email.primary_student_id ,  stud_email.calculated_field_1   as   email ,  case when pcm_email_type.eab_standard_value = 'Unmapped Value' then 'Unknown' else pcm_email_type.eab_standard_value end   as   email_type,stud_email.intake_date as intake_dt 
from    <[Enroll360].[Student Email].{fulfillment_ug_inquiries}>  as stud_email left outer join  <[Enroll360].[Partner Code Mapping].{convert}>  as pcm_email_type on pcm_email_type.field_name = 'email_type' and coalesce(stud_email.calculated_field_2, '') = coalesce(pcm_email_type.partner_value, '') 
where   <where_statement>  union all 
select  distinct  stud_email.primary_student_id ,  stud_email.calculated_field_3   as   email ,  case when pcm_email_type.eab_standard_value = 'Unmapped Value' then 'Unknown' else pcm_email_type.eab_standard_value end   as   email_type ,stud_email.intake_date as intake_dt
from    <[Enroll360].[Student Email].{fulfillment_ug_inquiries}>  as stud_email left outer join  <[Enroll360].[Partner Code Mapping].{convert}>  as pcm_email_type on pcm_email_type.field_name = 'email_type' and coalesce(stud_email.calculated_field_4, '') = coalesce(pcm_email_type.partner_value, '') 
where   <where_statement> ) as agg 
 
