where   <where_statement>  union all 
select  distinct  stud_email.primary_student_id ,  stud_email.calculated_field_1   as   email ,  case when pcm_email_type.eab_standard_value = 'Unmapped Value' then 'Unknown' else pcm_email_type.eab_standard_value end   as   email_type 
from    <[Enroll360].[Student Email].{fulfillment_ug_inquiries}>  as stud_email left outer join  <[Enroll360].[Partner Code Mapping].{convert}>  as pcm_email_type on pcm_email_type.field_name = 'email_type' and coalesce(stud_email.calculated_field_2, '') = coalesce(pcm_email_type.partner_value, '') 
where   <where_statement>  union all 
select  distinct  stud_email.primary_student_id ,  stud_email.calculated_field_3   as   email ,  case when pcm_email_type.eab_standard_value = 'Unmapped Value' then 'Unknown' else pcm_email_type.eab_standard_value end   as   email_type 
from    <[Enroll360].[Student Email].{fulfillment_ug_inquiries}>  as stud_email left outer join  <[Enroll360].[Partner Code Mapping].{convert}>  as pcm_email_type on pcm_email_type.field_name = 'email_type' and coalesce(stud_email.calculated_field_4, '') = coalesce(pcm_email_type.partner_value, '') 
where   <where_statement> ) as agg 
 
where  coalesce(agg.email, '')||coalesce(agg.email_type, '') <> ''

/*9-19-2024: we have a master query for this, please use that instead of a tenant*/

select 
null as CALCULATED_FIELD_1,null as CALCULATED_FIELD_2,null as CALCULATED_FIELD_3,null as CALCULATED_FIELD_4,null as CALCULATED_FIELD_5,null as CALCULATED_ID_FIELD,null as INTAKE_DATE,null as POPULATION_NAME,null as PRIMARY_STUDENT_ID,null as PHONE_NUMBER_TYPE,null as PHONE_NUMBER, null as PHONE_NUMBER_TYPE_EAB

select * 
	from <[Enroll360].[Partner Code Mapping].{convert}> 
		as pq where pq.eab_standard_value in ('Unmapped Value') 
		order by 1
		
/*  ALR Main bundle: */
select * from <[ALR].[Partner Code Mapping].{convert}> as pq where pq.eab_standard_value in ('Unmapped Value') order by RECORD_COUNT DESC*

/*  ALR Country bundle:  */
select * from <[ALR].[Partner Code Mapping].{convert_country}> as pq where pq.eab_standard_value in ('Unmapped Value') order by RECORD_COUNT DESC*

/*  ALR First source bundle:  */
select * from <[ALR].[Partner Code Mapping].{convert_first_source}> as pq where pq.eab_standard_value in ('Unmapped Value') order by RECORD_COUNT DESC*

select * 
	from <[Enroll360].[Partner Code Mapping].{convert}> 
		as pq where pq.eab_standard_value in ('Unmapped Value') 
		order by 1
		
/*  ALR Main bundle: */
select * from <[Enroll360].[Partner Code Mapping].{convert}> as pq where pq.eab_standard_value in ('Unmapped Value') order by 1 --RECORD_COUNT DESC*

/*  ALR Country bundle:  */
select * from <[Enroll360].[Partner Code Mapping].{convert_country}> as pq where pq.eab_standard_value in ('Unmapped Value') order by 1 --RECORD_COUNT DESC*

/*  ALR First source bundle:  */
select * from <[Enroll360].[Partner Code Mapping].{convert_first_source}> as pq where pq.eab_standard_value in ('Unmapped Value') order by 1 --RECORD_COUNT DESC*

select distinct
pd_app_funn.primary_student_id,

case when pd_app_funn.student_type is null then 'Other' 
else coalesce(pcm_stud_type.eab_standard_value,'Unmapped Value')
end student_type_eab,

case when pd_app_funn.current_entry_term is null then 'Fall' 
else coalesce(pcm_curr_entry_term.eab_standard_value,'Unmapped Value')
end entry_term_eab,

case when pd_app_funn.current_entry_year_as_academic_year is null then null
else coalesce(pcm_curr_entry_yr_acad.eab_standard_value,'Unmapped Value')
end entry_year_as_academic_year_eab,

pd_app_funn.application_id,

pd_app_funn.application_type,
case when pd_app_funn.application_type is null or pd_app_funn.application_type = '$$$' then null
    else coalesce(pcm_application_type.eab_standard_value,'Unmapped Value')
    end application_type_eab,
pd_app_funn.application_decision_type_code,
case when pd_app_funn.application_decision_type_code is null or pd_app_funn.application_decision_type_code = '$$$' then 'Unknown' 
else coalesce(pcm_decision_type.eab_standard_value,'Unmapped Value')
end application_decision_type_eab,

pd_app_funn.fulltime_or_parttime_status,
case when pd_app_funn.fulltime_or_parttime_status is null then 'Unknown' 
else coalesce(pcm_full_part_time.eab_standard_value,'Unmapped Value')
end fulltime_or_parttime_status_eab,

pd_app_funn.campus_resident_or_commuter_indicator,
case when pd_app_funn.campus_resident_or_commuter_indicator is null then null 
else coalesce(pcm_commuter.eab_standard_value,'Unmapped Value')
end campus_resident_or_commuter_indicator_eab,

pd_app_funn.campus_location,

case when pd_app_funn.area_of_academic_interest_or_major_for_undergraduate_school = '$$$' then null
else pd_app_funn.area_of_academic_interest_or_major_for_undergraduate_school
end area_of_academic_interest_or_major_for_undergraduate_school,

case when pd_app_funn.intended_program = '$$$' then null
else pd_app_funn.intended_program
end intended_program,
pd_app_funn.intended_school,

substring(pd_app_funn.application_started_date,0,10) as application_started_date,
pd_app_funn.application_started_indicator,
case when pd_app_funn.application_started_indicator is null then null
    else coalesce(pcm_application_started_indicator.eab_standard_value,'Unmapped Value')
    end application_started_indicator_eab,

case when pd_app_funn.application_incomplete_date = '$$$' then null
else substring(pd_app_funn.application_incomplete_date,0,10) 
end application_incomplete_date,

pd_app_funn.application_incomplete_indicator,
case when pd_app_funn.application_incomplete_indicator = '1' then '1'
    else coalesce(pcm_application_incomplete_indicator.eab_standard_value,'Unmapped Value')
    end application_incomplete_indicator_eab,

case when pd_app_funn.application_completed_date = '$$$' then null
else substring(pd_app_funn.application_completed_date,0,10)
end application_completed_date,

pd_app_funn.application_completed_indicator,
case when pd_app_funn.application_completed_indicator is null then null
    else coalesce(pcm_application_completed_indicator.eab_standard_value,'Unmapped Value')
    end application_completed_indicator_eab,

substring(pd_app_funn.application_withdrawal_date,0,10) as application_withdrawal_date,
pd_app_funn.application_withdrawal_indicator,

case when pd_app_funn.admit_date = '$$$' or pd_app_funn.admit_date = '' or pd_app_funn.admit_date is null then null
else substring(pd_app_funn.admit_date,0,10) 
end admit_date,

pd_app_funn.admit_indicator,
case when pd_app_funn.admit_indicator is null or pd_app_funn.admit_indicator = '$$$' then null
    else coalesce(pcm_admit_indicator.eab_standard_value,'Unmapped Value')
    end admit_indicator_eab,

substring(pd_app_funn.conditional_admit_date,0,10) as conditional_admit_date,
pd_app_funn.conditional_admit_indicator,
case when pd_app_funn.conditional_admit_indicator is null then null
    else coalesce(pcm_conditional_admit_indicator.eab_standard_value,'Unmapped Value')
    end conditional_admit_indicator_eab,
pd_app_funn.conditional_admit_reason,

substring(pd_app_funn.admit_notify_date,0,10) as admit_notify_date,
pd_app_funn.readmit_indicator_eab,
pd_app_funn.waitlist_admit,

substring(pd_app_funn.deny_date,0,10) as deny_date,
pd_app_funn.deny_indicator,
case when pd_app_funn.deny_indicator is null or pd_app_funn.admit_indicator = '$$$' then null
    else coalesce(pcm_deny_indicator.eab_standard_value,'Unmapped Value')
    end deny_indicator_eab,

substring(pd_app_funn.deferral_date,0,10) as deferral_date,

case when pd_app_funn_ug_other.deferral_indicator = '$$$' then null
else pd_app_funn_ug_other.deferral_indicator
end deferral_indicator,

pd_app_funn.deferral_from_term,
pd_app_funn.deferral_to_term,
pd_app_funn.future_deferral_indicator_eab,
pd_app_funn.previous_deferral_indicator_eab,

substring(pd_app_funn.waitlist_date,0,10) as waitlist_date,
pd_app_funn.waitlist_indicator,
case when pd_app_funn.waitlist_indicator is null then null
    else coalesce(pcm_waitlisted_indicator.eab_standard_value,'Unmapped Value')
    end waitlisted_indicator_eab,

case when pd_app_funn.deposit_confirmed_date = '$$$' then null
else substring(pd_app_funn.deposit_confirmed_date,0,10)
end deposit_confirmed_date,

pd_app_funn.deposit_confirmed_indicator,
case when pd_app_funn.deposit_confirmed_indicator is null or pd_app_funn.admit_indicator = '$$$' then null
    else coalesce(pcm_deposit_confirmed_indicator.eab_standard_value,'Unmapped Value')
    end deposit_confirmed_indicator_eab,

substring(pd_app_funn.housing_deposit_date,0,10) as housing_deposit_date,
pd_app_funn.housing_deposit_paid_or_waived_indicator,
case when pd_app_funn.housing_deposit_paid_or_waived_indicator is null then null
    else coalesce(pcm_housing_deposit_paid_or_waived_indicator.eab_standard_value,'Unmapped Value')
    end housing_deposit_paid_or_waived_indicator_eab,

substring(pd_app_funn.enrollment_date,0,10) as enrollment_date,
pd_app_funn.enrollment_indicator,
case when pd_app_funn.enrollment_indicator is null or pd_app_funn.admit_indicator = '$$$' then null
    else coalesce(pcm_enrollment_indicator.eab_standard_value,'Unmapped Value')
    end enrollment_indicator_eab,

case when pd_app_funn.withdrawal_date = '$$$' then null
else substring(pd_app_funn.withdrawal_date,0,10)
end withdrawal_date,

pd_app_funn.withdrawal_indicator,
case when pd_app_funn.withdrawal_indicator is null then null
    else coalesce(pcm_withdrawal_indicator.eab_standard_value,'Unmapped Value')
    end withdrawal_indicator_eab,

substring(pd_app_funn.cancel_date,0,10) as cancel_date,

pd_app_funn.test_optional,
case when pd_app_funn.test_optional is null or pd_app_funn.admit_indicator = '$$$' then null
    else coalesce(pcm_test_optional.eab_standard_value,'Unmapped Value')
    end test_optional_eab

from <[enrollment_services].[Partner Data Application Funnel].{entering_class}> pd_app_funn

left outer join <[enrollment_services].[Partner Data Application Funnel].{ug_other}> pd_app_funn_ug_other
on (pd_app_funn.primary_student_id = pd_app_funn_ug_other.primary_student_id
    and	coalesce(pd_app_funn.student_type,'') = coalesce(pd_app_funn_ug_other.student_type,'')
	and coalesce(pd_app_funn.current_entry_term,'') = coalesce(pd_app_funn_ug_other.current_entry_term,'')
	and coalesce(pd_app_funn.current_entry_year_as_academic_year,'') = coalesce(pd_app_funn_ug_other.current_entry_year_as_academic_year,''))

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_stud_type
on (pcm_stud_type.field_name = 'eab_student_type' and pcm_stud_type.partner_value = pd_app_funn.student_type)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_curr_entry_term
on (pcm_curr_entry_term.field_name = 'eab_entry_term' and pcm_curr_entry_term.partner_value = pd_app_funn.current_entry_term)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_curr_entry_yr_acad
on (pcm_curr_entry_yr_acad.field_name = 'eab_entry_year_academic' and pcm_curr_entry_yr_acad.partner_value = pd_app_funn.current_entry_year_as_academic_year)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_application_type
    on (pcm_application_type.field_name = 'eab_app_type' and pcm_application_type.partner_value = pd_app_funn.application_type)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_decision_type
on (pcm_decision_type.field_name = 'eab_app_decision_type' and pcm_decision_type.partner_value = pd_app_funn.application_decision_type_code)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_application_started_indicator
    on (pcm_application_started_indicator.field_name = 'eab_app_start_ind' and pcm_application_started_indicator.partner_value = pd_app_funn.application_started_indicator)
	
left outer join <[enrollment_services].[Partner Code Mapping]> pcm_application_incomplete_indicator
    on (pcm_application_incomplete_indicator.field_name = 'eab_app_incomplete_ind' and pcm_application_incomplete_indicator.partner_value = pd_app_funn.application_incomplete_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_application_completed_indicator
    on (pcm_application_completed_indicator.field_name = 'eab_app_complete_ind' and pcm_application_completed_indicator.partner_value = pd_app_funn.application_completed_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_admit_indicator
    on (pcm_admit_indicator.field_name = 'eab_admit_ind' and pcm_admit_indicator.partner_value = pd_app_funn.admit_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_conditional_admit_indicator
    on (pcm_conditional_admit_indicator.field_name = 'eab_cond_admit_ind' and pcm_conditional_admit_indicator.partner_value = pd_app_funn.conditional_admit_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_deny_indicator
    on (pcm_deny_indicator.field_name = 'eab_deny_ind' and pcm_deny_indicator.partner_value = pd_app_funn.deny_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_waitlisted_indicator
    on (pcm_waitlisted_indicator.field_name = 'eab_waitlist_ind' and pcm_waitlisted_indicator.partner_value = pd_app_funn.waitlist_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_deposit_confirmed_indicator
    on (pcm_deposit_confirmed_indicator.field_name = 'eab_deposit_ind' and pcm_deposit_confirmed_indicator.partner_value = pd_app_funn.deposit_confirmed_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_housing_deposit_paid_or_waived_indicator
    on (pcm_housing_deposit_paid_or_waived_indicator.field_name = 'eab_housing_deposit_paid_ind' and pcm_housing_deposit_paid_or_waived_indicator.partner_value = pd_app_funn.housing_deposit_paid_or_waived_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_enrollment_indicator
    on (pcm_enrollment_indicator.field_name = 'eab_enroll_ind' and pcm_enrollment_indicator.partner_value = pd_app_funn.enrollment_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_withdrawal_indicator
    on (pcm_withdrawal_indicator.field_name = 'eab_withdrawn_ind' and pcm_withdrawal_indicator.partner_value = pd_app_funn.withdrawal_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_full_part_time
on (pcm_full_part_time.field_name = 'eab_full_part_time' and pcm_full_part_time.partner_value = pd_app_funn.fulltime_or_parttime_status)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_commuter
on (pcm_commuter.field_name = 'eab_commuter_ind' and pcm_commuter.partner_value = pd_app_funn.campus_resident_or_commuter_indicator)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_test_optional
    on (pcm_test_optional.field_name = 'eab_test_optional' and pcm_test_optional.partner_value = pd_app_funn.test_optional)

select agg.*
from (select distinct calculated_field_3, pd_int.primary_student_id,

case when pd_int.student_type is null then 'Other' 
else coalesce(pcm_stud_type.eab_standard_value,'Unmapped Value')
end student_type_eab,

case when pd_int.current_entry_term is null then 'Fall' 
else coalesce(pcm_curr_entry_term.eab_standard_value,'Unmapped Value')
end entry_term_eab,

case when pd_int.current_entry_year_as_academic_year is null then null
else coalesce(pcm_curr_entry_yr_acad.eab_standard_value,'Unmapped Value')
end entry_year_as_academic_year_eab,

pd_int.campus_visit_count,
pd_int.campus_visit_flag,
case when pd_int.campus_visit_flag is null then null 
else coalesce(pcm_camp_vis.eab_standard_value,'Unmapped Value')
end campus_visit_flag_eab,

substring(pd_int.first_campus_visit_date,0,10) as first_campus_visit_date,
substring(pd_int.campus_visit_date,0,10) as campus_visit_date,
substring(pd_int.most_recent_campus_visit_date,0,10) as most_recent_campus_visit_date

from <[enrollment_services].[Partner Data Interaction]> pd_int

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_stud_type
on (pcm_stud_type.field_name = 'eab_student_type' and pcm_stud_type.partner_value = pd_int.student_type)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_curr_entry_term
on (pcm_curr_entry_term.field_name = 'eab_entry_term' and pcm_curr_entry_term.partner_value = pd_int.current_entry_term)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_curr_entry_yr_acad
on (pcm_curr_entry_yr_acad.field_name = 'eab_entry_year_academic' and pcm_curr_entry_yr_acad.partner_value = pd_int.current_entry_year_as_academic_year)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_camp_vis
on (pcm_camp_vis.field_name = 'eab_campus_visit_ind' and pcm_camp_vis.partner_value = pd_int.campus_visit_flag)
	  ) agg
  where coalesce(agg.calculated_field_3,'') = 'H'
  AND agg.primary_student_id NOT IN ('659639850', '813705685', '135722493', '611850754', '550236554', '975378693')

select distinct
pd_race_eth.primary_student_id,

case when pd_race_eth.student_type is null then 'Freshman' 
else coalesce(pcm_stud_type.eab_standard_value,'Unmapped Value')
end student_type_eab,

case when pd_race_eth.current_entry_term is null then 'Fall' 
else coalesce(pcm_curr_entry_term.eab_standard_value,'Unmapped Value')
end entry_term_eab,

case when pd_race_eth.current_entry_year_as_academic_year is null then null
else coalesce(pcm_curr_entry_yr_acad.eab_standard_value,'Unmapped Value')
end entry_year_as_academic_year_eab,

case when pd_race_eth.american_indian_or_alaska_native is null then null
else coalesce(pcm_amer_ind.eab_standard_value,'Unmapped Value')
end american_indian_or_alaska_native_eab,

case when pd_race_eth.asian is null then null
else coalesce(pcm_asian.eab_standard_value,'Unmapped Value')
end asian_eab,

case when pd_race_eth.black_or_african_american is null then null
else coalesce(pcm_afr_amer.eab_standard_value,'Unmapped Value')
end black_or_african_american_eab,

case when pd_race_eth.middle_eastern is null then null
else coalesce(pcm_mid_east.eab_standard_value,'Unmapped Value')
end middle_eastern_eab,

case when pd_race_eth.multiracial is null then null
else coalesce(pcm_multiracial.eab_standard_value,'Unmapped Value')
end multiracial_eab,

case when pd_race_eth.prefer_not_to_respond is null then null
else coalesce(pcm_no_response.eab_standard_value,'Unmapped Value')
end prefer_not_to_respond_eab,

case when pd_race_eth.other_race is null then null
else coalesce(pcm_other.eab_standard_value,'Unmapped Value')
end other_race_eab,

case when pd_race_eth.native_hawaiian_or_other_pacific_islander is null then null
else coalesce(pcm_pac_island.eab_standard_value,'Unmapped Value')
end native_hawaiian_or_other_pacific_islander_eab,

case when pd_race_eth.unknown is null then null
else coalesce(pcm_unknown.eab_standard_value,'Unmapped Value')
end unknown_eab,

case when pd_race_eth.white is null then null
else coalesce(pcm_white.eab_standard_value,'Unmapped Value')
end white_eab,

case when pd_race_eth.ethnicity is null then 'Unknown' 
else coalesce(pcm_eth.eab_standard_value,'Unmapped Value')
end ethnicity_eab,

pd_race_eth.american_indian_or_alaska_native,
pd_race_eth.asian,
pd_race_eth.black_or_african_american,
pd_race_eth.middle_eastern,
pd_race_eth.multiracial,
pd_race_eth.prefer_not_to_respond,
pd_race_eth.other_race,
pd_race_eth.native_hawaiian_or_other_pacific_islander,
pd_race_eth.unknown,
pd_race_eth.white,
pd_race_eth.hispanic,
pd_race_eth.ethnicity,
pd_race_eth.race

from <[enrollment_services].[Partner Data Race and Ethnicity]> pd_race_eth

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_stud_type
on (pcm_stud_type.field_name = 'eab_student_type' and pcm_stud_type.partner_value = pd_race_eth.student_type)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_curr_entry_term
on (pcm_curr_entry_term.field_name = 'eab_entry_term' and pcm_curr_entry_term.partner_value = pd_race_eth.current_entry_term)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_curr_entry_yr_acad
on (pcm_curr_entry_yr_acad.field_name = 'eab_entry_year_academic' and pcm_curr_entry_yr_acad.partner_value = pd_race_eth.current_entry_year_as_academic_year)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_eth
on (pcm_eth.field_name = 'eab_ethnicity' and pcm_eth.partner_value = pd_race_eth.ethnicity)


left outer join <[enrollment_services].[Partner Code Mapping]> pcm_amer_ind
on (pcm_amer_ind.field_name = 'eab_race_native_american_ind' and pd_race_eth.race like pcm_amer_ind.partner_value)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_asian
on (pcm_asian.field_name = 'eab_race_asian_ind' and pd_race_eth.race like pcm_asian.partner_value)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_afr_amer
on (pcm_afr_amer.field_name = 'eab_race_black_ind' and pd_race_eth.race like pcm_afr_amer.partner_value)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_mid_east
on (pcm_mid_east.field_name = 'eab_race_middle_eastern' and pd_race_eth.race like pcm_mid_east.partner_value)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_multiracial
on (pcm_multiracial.field_name = 'eab_race_multiracial' and pd_race_eth.race like pcm_multiracial.partner_value)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_no_response
on (pcm_no_response.field_name = 'eab_race_no_response' and pd_race_eth.race like pcm_no_response.partner_value)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_other
on (pcm_other.field_name = 'eab_race_other' and pd_race_eth.race like pcm_other.partner_value)

