                          from   <sorter_srt_desc1> as df_asc), AA10_downfill_major_cd1 as ( <AA10_downfill_major_cd1>), AA11_prev_downfill_major_cd1 as ( <AA11_prev_downfill_major_cd1>), AA12_major_cd_2_partition_cd_1 as ( <AA12_major_cd_2_partition_cd_1>), AA13_final_major_cd_1_downfill_cd_1 as ( <AA13_final_major_cd_1_downfill_cd_1>), AA14_prev_major_cd_1 as ( <AA14_prev_major_cd_1>), AA15_backfill_cd_1_downfill_cd_2_partitions as ( <AA15_backfill_cd_1_downfill_cd_2_partitions>), AA16_new_cd_1_downfill_cd_2 as ( <AA16_new_cd_1_downfill_cd_2>), AA17_prev_major_cd_2 as ( <AA17_prev_major_cd_2>), AA18_backfill_cd_2_partition_downfill_cd_3_partition as ( <AA18_backfill_cd_2_partition_downfill_cd_3_partition>), AA19_new_cd_2_downfill_cd_3 as ( <AA19_new_cd_2_downfill_cd_3>), AA20_prev_major_cd_3 as ( <AA20_prev_major_cd_3>), AA21_backfill_cd_3 as ( <AA21_backfill_cd_3>), AA22_final_3_values as ( <AA22_final_3_values>), AA23_prev_major_cd_4 as ( <AA23_prev_major_cd_4>), AA24_downfill_code_4_partition as ( <AA24_downfill_code_4_partition>), AA25_downfill_code_4_values as ( <AA25_downfill_code_4_values>), AA26_backfill_code_4_partition as ( <AA26_backfill_code_4_partition>), AA27_final_code_4_values as ( <AA27_final_code_4_values>), ST_student_term_sweep as ( <student_term_sweep>) 
