select   so_sr_ct.out_major_cd   as   Major_Code,  so_sr_ct.out_major_desc   as   major_name ,  so_sr_ct.out_cip_code   as   cip_code 
 
from   (
select   ex_ex_hr.out_major_cd   as   out_major_cd ,  ex_ex_hr.out_major_desc   as   out_major_desc ,  ex_ex_hr.out_cip_code   as   out_cip_code ,  row_number() over (order by  ex_ex_hr.out_major_cd   asc ,  ex_ex_hr.out_major_desc   asc ,  ex_ex_hr.out_cip_code   asc ,  ex_ex_hr.rownumber   ASC )   as   rownumber 
from   (
select   so_os_42.Major_Code   as   out_major_cd ,  ltrim(rtrim(so_os_42.major_name))   as   out_major_desc ,  ltrim(rtrim(so_os_42.cip_code))   as   out_cip_code ,  row_number() over (order by  (
select   0 
)   asc )   as   rownumber 
from    <[Panto_JMN_POC].[major_lkp]>  as so_os_42 
) as ex_ex_hr 
order by   ex_ex_hr.out_major_cd   asc ,  ex_ex_hr.out_major_desc   asc ,  ex_ex_hr.out_cip_code   asc ,  ex_ex_hr.rownumber   ASC 
) as so_sr_ct

SELECT 'Condition Met' as col1
FROM dual 
WHERE EXISTS (
    SELECT 1 FROM dual
);

select   a.dmpEabId_null_count   as   measure 
 
from   (
select   ((
select   count( <column_item> )   as   record_total 
from    <CategoryOne>  as a 
where  dmp_eab_id is not null
) / (
select   count( <column_item> )   as   total 
from    <CategoryOne>  as b 
))   as   dmpEabId_null_count 
) as a

select   CONCAT(a.cd, '$$', b.cat_yr)   as   nk ,  a.cd ,  b.cat_yr   as   cat_yr ,  a.name ,  a.desc ,  a.credits ,  a.enrollment_notes ,  a.area_of_study ,  a.concentration ,  a.credential ,  a.cip ,  a.is_transfer ,  a.is_active 
 
from    <[Smart Guidance SGD].[Program]>  as a left join (
select  distinct  cat_yr 
from    <[Smart Guidance SGD].[Term]>  as a 
where  cat_yr > 2017 and cat_yr < 2022
) as b on 1= 1

select   a.nk ,  a.student ,  a.term ,  CONCAT(a.program, '$$', b.cat_yr)   as   program ,  a.is_active 
 
from    <[Smart Guidance SGD].[Student Term]>  as a join (
select   a.student ,  max(term)   as   m 
from    <[Smart Guidance SGD].[Student Term]>  as a 
group by   a.student 
) as c on a.student = c.student and a.term = c.m left join  <[Smart Guidance SGD].[Term]>  as b on a.term = b.nk
